#%% Pre-Processing
'''
This section cleans and standdizes all the data via the following functions
>data_cleaner
Takes df as argument
Removes projects outside of scope (those that are not successful or failed)
Removes predictors that are not relavant
Returns predictors in X and state in y 

>get_dummies
Takes df as argument
returns dummified df

>feature_eng 
Takes df as argument
Not used
Can help with the price preformance of currencies (an economic measure of real money power)
returns df with addtional PPP column

>Scale_vals
takes df as argument
scales calues using the minmax method
returns scalled df

>Standardize_dummies
Takes df as argument
Ensures that the the 


>Gr_standardizer
Takes df as argument
Drops columns from garding set not in training set to standardize the training and testing sets


'''
#Removes projects outside of scope (those that are not successful or failed)
#Removes predictors that are not relavant
#Returns predictors in X and state in y 
def data_cleaner(df):
    # df = df.dropna()
    
    #define states to keep
    states = ["successful", "failed"]
    
    #Drop rows that contain any value in the list
    df = df[df.state.isin(states) == True]
    
    #disable warnings
    pd.options.mode.chained_assignment = None  # default='warn'
    
    #Convert goal to usd
    df["goal_inUS"]=(df["goal"]*df["static_usd_rate"])
    
    #resetting warnings
    pd.options.mode.chained_assignment = 'warn'
    
    # Setup the variables that are used. The dropped variables are commented out to demonstrate which ones were used 
    df = df[[
    'state',
    'country',
    'deadline_weekday',
    'category',
    'name_len','blurb_len_clean',
    'launched_at_weekday','launched_at_month','launched_at_day','launched_at_yr','launched_at_hr',
    'deadline_month','deadline_day','deadline_yr','deadline_hr',
    'created_at_month','created_at_day','created_at_hr',
    'create_to_launch_days',
    'launch_to_deadline_days',
    'goal_inUS']]

#Excluded predictors
#unique Identifiers        #'id','name',                                
#not available at launch   #'goal','pledged','state_changed_at',  staff_pick','spotlight','backers_count',  
                             ## 'state_changed_at_weekday','state_changed_at_month','state_changed_at_day',
                             ###'state_changed_at_yr','state_changed_at_hr','launch_to_state_change_days',
#not used-redundant        #'currency','created_at','launched_at','deadline','name_len_clean','blurb_len',       
#not used                  # 'disable_communication','static_usd_rate','usd_pledged',# 'created_at_weekday',
                            ##'created_at_yr',

    #target variable set
    y = df["state"]
    
    #predictors set
    X = df.drop(["state"], axis=1)
    
    #dumify the variables in the predictor set
    X=get_dummies(X)
    
    #standardize the order of the columns
    X=Sort_frame(X)
    
    return X,y

def Sort_frame(df):
    df = df.sort_index(axis=1)
    return df



#Ensures dummification of the categorical vvariables like weekday
def get_dummies(df):
    df=pd.get_dummies(df)
    #df=standardize_dummies(df)
    return df
    
#Ensures that the dummy variabels between the test and train set are consitent.
#without this the predictions do not have any consistency
def standardize_dummies(X,XG):
    list_fields=X.columns.to_list()
    for i in list_fields:
        if i not in XG.columns:
            XG[i] = 0
    return X,XG

