#Ensure that the values are scalled approrpiately
def scale_vals(df):
    #from sklearn.preprocessing import StandardScaler
    #scaled_features=StandardScaler().fit_transform(df)
    
    from sklearn.preprocessing import MinMaxScaler
    scaled_features=MinMaxScaler().fit_transform(df)

    #Standard Scaler returns numpy ndarray but dataframe preferered and required for other methods
    df=pd.DataFrame(scaled_features, index=df.index, columns=df.columns)
    
    return df

#Ensures that the grading set and the training set have the same columns. Important if a project is from a country not previously seen
def Gr_standardizer(X,XG):
    for i in XG.columns.to_list():
        if i not in X.columns.to_list():
            XG=XG.drop([i],axis=1)
    return X,XG

